UInt16 b69_tree_opcode(int op) {
    if (op < 0 || op >= B69_NUM_OPCODES || b69_opcode_map[op] == NONE) {
        fprintf(stderr, "b69 opcode 0x%X has no tree opcode (OpcodeMap69.c)\n", op);
        fflush(stderr);
        abort();
    }
    return b69_opcode_map[op];
}

OpcodeDef* b69_tree_def(int op) {
    return &data_006115F8[b69_tree_opcode(op)];
}
